-- DMF0035_CLOUD_20260820 / A_DB/23_MSG_LBL_MNU_SYNC.sql
-- SCM_ADM_MSG_M — MSG/LBL/MNU 는 동일 테이블(MSG_TP_CD 로 구분). 라벨 전용 테이블은 없음(딕셔너리 실측).
-- 축 = ① FE 폴더 전수 grep (MSG|LBL|MNU)\d{5} LIVE 20종  ② MNU_M.MNU_MSG_ID 2종(MNU00691/MNU00020)
--   주석에만 등장하는 LBL00774(Mail Setup·SYS0017 점유) / MSG00109 는 제외 (hook #138).
-- 신규 채번분 = LBL00852~854 (Day/Week/Manual, 2026-08-06). 나머지는 기존 코드 재사용.

MERGE INTO SCM_MGR.SCM_ADM_MSG_M T
USING DUAL ON (T.MSG_ID = 'LBL00001' AND T.LANG_CD = 'CN')
WHEN MATCHED THEN UPDATE SET T.MSG_NM = 'Div.', T.MSG_DESC = NULL, T.MSG_TP_CD = 'LBL', T.USE_YN = 'Y', T.CREATED_BY = 'SYSTEM', T.CREATION_DATE = TO_DATE('20260213155329','YYYYMMDDHH24MISS'), T.LAST_UPDATED_BY = 'minyonglee1', T.LAST_UPDATE_DATE = TO_DATE('20260628114916','YYYYMMDDHH24MISS')
WHEN NOT MATCHED THEN INSERT (MSG_ID, LANG_CD, MSG_NM, MSG_DESC, MSG_TP_CD, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
VALUES ('LBL00001', 'CN', 'Div.', NULL, 'LBL', 'Y', 'SYSTEM', TO_DATE('20260213155329','YYYYMMDDHH24MISS'), 'minyonglee1', TO_DATE('20260628114916','YYYYMMDDHH24MISS'));

